/* angle may be any int (negative / >4096); the original masks to the 4096-word table.
 * sin = low 16 (sign-extended), cos = high 16. Byte-true DAT_800794c4 lookup. */
int re15_sin_q12(int angle_4096)
{
    uint32_t w = re15_trig_lut[(uint32_t)angle_4096 & 0xfff];
    return (int)(int16_t)(w & 0xffff);
}
int re15_cos_q12(int angle_4096)
{
    uint32_t w = re15_trig_lut[(uint32_t)angle_4096 & 0xfff];
    return (int)(int16_t)(w >> 16);
}
